                else:
                    return False
            if any(bad(a) for a in args):
                # one of the args failed to compute to a finite precision
                return
        except (TypeError, ValueError):
            # Input can't be converted to mpf
            return

        v = func(*args)
        if v is None:  # mpmath function returned None
            return
        if hasattr(v, "_mpf_"):
            return Float(v, prec)
        return Float._new(v._mpc_, prec, round=round_floor)
